text:
{
  "outline": [
    {
      "title": "极限：微积分的地基",
      "summary": "学习数列极限和函数极限的定义（ε-N 和 ε-δ 语言）、性质，以及两个重要极限，为后续导数与积分打下基础。",
      "kc_names": ["数列极限", "函数极限", "极限与连续"]
    },
    {
      "title": "无穷小量与连续性",
      "summary": "掌握无穷小量的比较、等价无穷小替换技巧，以及函数连续性的概念与闭区间上连续函数的三大定理。",
      "kc_names": ["无穷小量", "等价无穷小替换定原则", "函数的连续性"]
    },
    {
      "title": "导数与微分计算",
      "summary": "理解导数的定义与几何意义，熟记基本初等函数导数表，掌握四则、复合、反函数求导法则，并学习高阶导数和隐函数求导。",
      "kc_names": ["导数", "基本初等函数导数表", "求导法则", "高阶导数"]
    },
    {
      "title": "微分中值定理与洛必达法则",
      "summary": "学习罗尔、拉格朗日、柯西三大中值定理，以及洛必达法则，用于证明等式、不等式和求解未定式极限。",
      "kc_names": ["罗尔定理", "拉格朗日中值定理", "柯西中值定理", "洛必达法则"]
    },
    {
      "title": "泰勒公式：多项式逼近",
      "summary": "掌握泰勒多项式与余项（佩亚诺、拉格朗日），熟记常用函数的麦克劳林展开，并应用于近似计算和求极限。",
      "kc_names": ["泰勒公式", "麦克劳林展开", "多项式逼近", "误差(余项)"]
    },
    {
      "title": "积分：从不定到定积分",
      "summary": "学习不定积分与基本积分表，掌握换元积分法和分部积分法，理解定积分的定义、性质及牛顿-莱布尼茨公式，并了解定积分在面积、体积等几何问题中的应用。",
      "kc_names": ["不定积分", "换元积分法", "分部积分法", "定积分"]
    }
  ],
  "glossary": [
    {"term": "数列极限", "definition": "当项数无限增大时，数列趋近于一个确定的常数，用 ε-N 语言严格描述。"},
    {"term": "函数极限", "definition": "当自变量趋近某一点或无穷时，函数值趋近于一个常数，用 ε-δ 语言定义。"},
    {"term": "无穷小量", "definition": "极限为零的变量，是微积分中比较和替换的基础。"},
    {"term": "等价无穷小", "definition": "两个无穷小量之比极限为1，可在乘除运算中互相替换以简化计算。"},
    {"term": "导数", "definition": "函数在某点的瞬时变化率，几何上表示切线的斜率。"},
    {"term": "微分中值定理", "definition": "在闭区间上连续、开区间内可导的函数，区间内至少存在一点，其导数等于平均变化率。"},
    {"term": "泰勒公式", "definition": "用多项式逼近光滑函数，并给出误差（余项）的表达式。"},
    {"term": "定积分", "definition": "函数在区间上的累积和，定义为黎曼和的极限，用于计算面积、体积等。"}
  ],
  "suggested_questions": [
    "如何用 ε-N 语言证明数列 $1/n$ 的极限为 0？",
    "等价无穷小替换在加减法中为什么不能直接使用？",
    "闭区间上连续函数的零点存在定理如何用于求方程近似根？",
    "洛必达法则适用于哪些类型的未定式？使用时需注意什么？",
    "如何利用泰勒公式近似计算 $\\sin(0.1)$ 并估计误差？",
    "牛顿-莱布尼茨公式如何将定积分与原函数联系起来？"
  ]
}
